// NEO fork — the committed dictionary data still matches its manifest (adr-003)
//
// The shards are generated by neo-ext/tools/build-oewn.js. This test is the
// guard against a half-regenerated directory or a dropped licence.

'use strict';

const test = require('node:test');
const assert = require('node:assert');
const fs = require('node:fs');
const path = require('node:path');
const zlib = require('node:zlib');

const DIR = path.join(__dirname, '..', 'neo-ext', 'dictionary', 'en');
const SHARDS = path.join(DIR, 'shards');
const MAX_GZ = 7 * 1024 * 1024;
const POS = ['noun', 'verb', 'adj', 'adv'];
const { HEADWORD } = require('../neo-ext/lib/word-forms.js');

const manifest = () => JSON.parse(fs.readFileSync(path.join(DIR, 'manifest.json'), 'utf8'));

function shardNames() {
  return fs.readdirSync(SHARDS).filter((f) => f.endsWith('.json.gz')).sort();
}

function readShard(name) {
  return JSON.parse(zlib.gunzipSync(fs.readFileSync(path.join(SHARDS, name))).toString('utf8'));
}

test('manifest: provenance and counts', () => {
  const m = manifest();
  assert.equal(m.format, 1);
  assert.equal(m.language, 'en');
  assert.equal(m.edition, '2025');
  assert.match(m.sha256, /^[0-9a-f]{64}$/);
  assert.match(m.source, /^https:\/\/github\.com\/globalwordnet\/english-wordnet\//);
  assert.ok(m.headwords > 100000, `headwords ${m.headwords}`);
  assert.ok(m.senses > 150000, `senses ${m.senses}`);
  assert.equal(m.shards, 26);
  assert.ok(m.gzBytes > 0 && m.gzBytes < MAX_GZ, `gzBytes ${m.gzBytes}`);
});

test('shards: one per letter, keys in that letter, counts add up', () => {
  const m = manifest();
  const names = shardNames();
  assert.deepEqual(names, 'abcdefghijklmnopqrstuvwxyz'.split('').map((c) => `${c}.json.gz`));

  let headwords = 0;
  let senses = 0;
  let examples = 0;
  let bytes = 0;
  for (const name of names) {
    const letter = name[0];
    const file = path.join(SHARDS, name);
    bytes += fs.statSync(file).size;
    const entries = readShard(name);
    const keys = Object.keys(entries);
    assert.ok(keys.length > 0, `${name} is empty`);
    for (const key of keys) {
      assert.equal(key[0], letter, `${key} in ${name}`);
      assert.ok(!/[()]/.test(key), `${key} is not a plain word`);
      assert.ok(HEADWORD.test(key), `${key} is not a headword the lookup can produce`);
      assert.ok(Array.isArray(entries[key]) && entries[key].length, `${key} has no senses`);
      for (const sense of entries[key]) {
        assert.ok(POS.includes(sense.pos), `${key}: ${sense.pos}`);
        assert.equal(typeof sense.def, 'string');
        assert.ok(sense.def.trim().length > 0, `${key} has an empty definition`);
        assert.ok(!/\(noun\)|\(verb\)|\(adj\)|\(adv\)/.test(sense.def), `${key} carries a marker`);
        if (sense.ex !== undefined) {
          assert.ok(Array.isArray(sense.ex), `${key}: examples must be a list`);
          assert.ok(sense.ex.length >= 1 && sense.ex.length <= 4, `${key}: ${sense.ex.length} examples`);
          for (const example of sense.ex) {
            assert.equal(typeof example, 'string');
            assert.ok(example.trim().length > 0);
            examples += 1;
          }
        }
        senses += 1;
      }
    }
    headwords += keys.length;
  }
  assert.equal(headwords, m.headwords);
  assert.equal(senses, m.senses);
  assert.equal(bytes, m.gzBytes);
  assert.ok(examples > 10000, `only ${examples} examples carried`);
});

test('shards: a known word has noun and verb senses with examples', () => {
  const batch = readShard('b.json.gz').batch;
  assert.ok(Array.isArray(batch) && batch.length >= 3, `batch has ${batch && batch.length} senses`);
  const pos = new Set(batch.map((s) => s.pos));
  assert.ok(pos.has('noun') && pos.has('verb'));
  assert.ok(batch.some((s) => s.def.includes('loaves of bread')), 'the bakery sense is present');
  assert.ok(batch.some((s) => Array.isArray(s.ex) && s.ex.length), 'a sense keeps its examples');
  assert.ok(!batch.some((s) => /\(noun\)|\(verb\)/.test(s.def)), 'no part of speech inside a definition');
});

test('dictionary: a word with many senses is a long entry', () => {
  const run = readShard('r.json.gz').run;
  assert.ok(Array.isArray(run) && run.length > 40, `run has ${run && run.length} senses`);
  assert.ok(run.some((s) => s.ex && s.ex.length), 'run carries examples');
});

test('data: both licences ship beside the data', () => {
  const cc = fs.readFileSync(path.join(DIR, 'LICENSE.md'), 'utf8');
  assert.match(cc, /Creative Commons Attribution 4\.0/);
  assert.match(cc, /Princeton/);
  assert.match(cc, /Open English Wordnet/i);
  const wn = fs.readFileSync(path.join(DIR, 'WNDB_License.txt'), 'utf8');
  assert.match(wn, /Princeton/);
  assert.match(wn, /Permission to use, copy, modify and distribute/);
});
